/* LISTENING (supplément 1) — Listen and Choose a Response + annonces. Ajout via push. */
CONTENT.lcr.push(
  { id: "lx001", diff: 2, g: "W", p: "I'm going to grab a sandwich. Want anything?", o: ["A bottle of water would be great, thanks.", "Yes, I grabbed it.", "The sandwich is on the table.", "I want to go home."], a: 0, x: "Offre → réponse précise." },
  { id: "lx002", diff: 2, g: "W", p: "Has the professor posted the grades yet?", o: ["The grades are good.", "Yes, I posted a letter.", "The professor is on leave.", "I checked an hour ago, and nothing yet."], a: 3, x: "Question au present perfect → vérification récente." },
  { id: "lx003", diff: 3, g: "M", p: "They're saying the strike could drag on for weeks.", o: ["The drag race was loud.", "The strikers walked out.", "That would really disrupt the semester.", "The strike was in the news last week."], a: 2, x: "Information → conséquence logique." },
  { id: "lx004", diff: 2, g: "W", p: "I wish you'd told me you were stopping by.", o: ["I stopped at the bakery.", "I would have, but my plans changed at the last minute.", "I wish it were summer.", "I told you yesterday."], a: 1, x: "Reproche (« I wish you'd ») → justification." },
  { id: "lx005", diff: 2, g: "W", p: "I overslept and missed the first lecture.", o: ["I sleep a lot.", "Don't worry, I can lend you my notes.", "Lectures are long.", "The first one was early."], a: 1, x: "Problème → aide." },
  { id: "lx006", diff: 3, g: "W", p: "We were hoping you could shed some light on the situation.", o: ["Sure — let me walk you through what happened.", "The light is on.", "I shed my coat.", "The light is too dim."], a: 0, x: "« shed light on » = éclaircir → explication." },
  { id: "lx007", diff: 2, g: "M", p: "Do you think we should call the landlord about the heating?", o: ["The landscape is lovely.", "I heard it was hot.", "Yes, he called.", "Yes, it's been broken for three days now."], a: 3, x: "Réponse positive justifiée." },
  { id: "lx008", diff: 2, g: "M", p: "If you're not busy, could you give me a hand moving this desk?", o: ["My hand hurts.", "The desk is by the window.", "Sure, just let me put my bag down.", "The desk is heavy."], a: 2, x: "Demande conditionnelle → accord." },
  { id: "lx009", diff: 3, g: "W", p: "Don't get me wrong — I like Mark, but he's not right for this role.", o: ["I don't get the wrong change.", "I like the role.", "I see your point. What kind of person do you have in mind?", "Mark is meeting me for lunch."], a: 2, x: "« Don't get me wrong » introduit une critique → suite." },
  { id: "lx010", diff: 2, g: "W", p: "I'm trying to get a refund for this printer.", o: ["Yes, it prints very well.", "Do you have the receipt with you?", "A fund is a good idea.", "I tried to print it."], a: 1, x: "Contexte service client : question de vérification." },
  { id: "lx011", diff: 1, g: "M", p: "Where do I turn in my application?", o: ["At the admissions office, window three.", "I turned left at the corner.", "It's due at the end of October.", "The application was long."], a: 0, x: "« Where » → un lieu. Piège : « turn » dans un autre sens." },
  { id: "lx012", diff: 1, g: "M", p: "Sorry I'm late — the bus broke down.", o: ["Yes, I broke it down.", "The class is down the hall.", "It was a very old bus.", "No problem, we've only just started."], a: 3, x: "Excuse → réaction rassurante." },
  { id: "lx013", diff: 1, g: "M", p: "Who's giving the talk this afternoon?", o: ["At three o'clock in the auditorium.", "It was a very long talk.", "I'm talking to my roommate.", "A professor from Oxford, I think."], a: 3, x: "« Who » → une personne. Piège : réponse à « when / where »." },
  { id: "lx014", diff: 3, g: "M", p: "She's been under the weather all week.", o: ["The weather was nice.", "She was caught in the rain.", "I hope she's feeling better soon.", "It's raining all week."], a: 2, x: "« under the weather » = patraque. Réaction empathique." },
  { id: "lx015", diff: 1, g: "M", p: "Could I get a receipt, please?", o: ["I received it last week.", "Of course, here you go.", "The recipe is on the back.", "It was a great deal."], a: 1, x: "Demande de service → accord. Piège sonore : « receipt » / « recipe »." },
  { id: "lx016", diff: 2, g: "W", p: "Do you know if the pharmacy delivers?", o: ["They do, but only within two miles.", "No, I deliver the mail.", "The pharmacy was founded in 1990.", "It was delivered yesterday."], a: 0, x: "« Do you know if » → information factuelle." },
  { id: "lx017", diff: 2, g: "W", p: "We'd better get going if we don't want to miss the opening remarks.", o: ["Right. I'll text Tom and tell him to meet us there.", "I'm going to bed.", "I wrote my remarks down.", "Yes, we'd better."], a: 0, x: "« We'd better » → action rapide." },
  { id: "lx018", diff: 1, g: "W", p: "Have you been to the new sports center yet?", o: ["Sports are popular in my country.", "The center costs thirty dollars a month.", "I haven't yet another one.", "Not yet, but I'm planning to go on Saturday."], a: 3, x: "Question au present perfect → « Not yet » + projet." },
  { id: "lx019", diff: 1, g: "M", p: "How long have you lived here?", o: ["I live in the dorm.", "For ten dollars a week.", "Since I started college, about three years.", "It's a very long street."], a: 2, x: "« How long have you… » → durée avec « since / for »." },
  { id: "lx020", diff: 2, g: "M", p: "Do you have a minute to talk about my paper?", o: ["It's one minute past three.", "Sure, come by my office after lunch.", "The paper is very thin.", "I talked about it yesterday."], a: 1, x: "Demande d'entretien → accord + moment." },
  { id: "lx021", diff: 2, g: "W", p: "Would it be possible to reschedule my appointment?", o: ["It's not possible to schedule.", "How about Wednesday at two instead?", "The appointment was yesterday.", "Yes, it was possible."], a: 1, x: "Demande polie → contre-proposition d'horaire." },
  { id: "lx022", diff: 3, g: "M", p: "I'd hate to think what would've happened if we'd missed the flight.", o: ["Don't even go there — let's just be glad we made it.", "I hate flights.", "We had missed lunch.", "The flight was on time."], a: 0, x: "Hypothèse passée (3e conditionnel) → apaisement." },
  { id: "lx023", diff: 3, g: "M", p: "Not to be rude, but I think you've got the wrong room.", o: ["I'm not being rude.", "I roomed with her last year.", "No, I think it's right.", "Oh no, you're right. I'm so embarrassed."], a: 3, x: "Remarque polie → gêne et correction." },
  { id: "lx024", diff: 3, g: "W", p: "Would you say the proposal is more or less ready to submit?", o: ["I'd say hello.", "The proposal is ten pages.", "More or less, though the budget section still needs a final pass.", "The proposal was rejected."], a: 2, x: "Réponse nuancée (« more or less »)." },
  { id: "lx025", diff: 2, g: "W", p: "How come the cafeteria is closed so early today?", o: ["I came in time.", "It's a close call.", "There's a staff meeting this afternoon.", "The cafeteria is clean."], a: 2, x: "« How come » = pourquoi → raison." },
  { id: "lx026", diff: 1, g: "W", p: "Is this café self-service?", o: ["Yes, I serve myself dinner at home.", "No, a waiter will come to your table.", "The coffee is excellent here.", "There's a service charge."], a: 1, x: "Question oui/non sur le fonctionnement du lieu." },
  { id: "lx027", diff: 3, g: "W", p: "If it were up to me, I'd move the deadline to next month.", o: ["Unfortunately, it's not up to either of us.", "I'm up to my neck in work.", "Next month is October.", "The movers arrive at noon."], a: 0, x: "Hypothèse → rappel de réalité." },
  { id: "lx028", diff: 1, g: "W", p: "Can I pay by check?", o: ["Yes, I checked the price.", "The payment was late.", "A check mark is fine.", "I'm sorry, we only accept cash or card."], a: 3, x: "Question de possibilité → refus poli. Piège : « check » répété." },
  { id: "lx029", diff: 2, g: "M", p: "The cafeteria ran out of vegetarian options by noon.", o: ["Noon is the middle of the day.", "I run out of time too.", "The vegetables were fresh.", "They should order more, then."], a: 3, x: "Constat → commentaire logique." },
  { id: "lx030", diff: 1, g: "M", p: "Is the museum free on Sundays?", o: ["The museum has a new exhibit.", "Sundays are my days off.", "Only after two in the afternoon.", "It's closed all day Monday."], a: 2, x: "Question oui/non → réponse partielle précise." },
  { id: "lx031", diff: 3, g: "W", p: "I'd love to help, but my hands are tied.", o: ["I tied my shoes.", "I understand. I'll ask someone else.", "I'd love a tie.", "Yes, help is wanted."], a: 1, x: "« my hands are tied » = je n'y peux rien." },
  { id: "lx032", diff: 3, g: "M", p: "I took the liberty of booking us a table.", o: ["That's very thoughtful of you, thank you.", "Liberty is a statue.", "I tabled the discussion.", "The book was nice."], a: 0, x: "« take the liberty of » = prendre l'initiative → remerciement." },
  { id: "lx033", diff: 2, g: "W", p: "The projector in room two isn't working.", o: ["I'll ask the technician to take a look.", "I projected the film.", "Room two is bigger.", "It works for me."], a: 0, x: "Signalement de problème → action." },
  { id: "lx034", diff: 3, g: "M", p: "You should really get that cough checked out.", o: ["I checked out the library.", "I coughed all night.", "I got it at the pharmacy.", "I know, I keep putting it off."], a: 3, x: "Conseil → aveu de procrastination (« put off »)." },
  { id: "lx035", diff: 3, g: "W", p: "I'm inclined to go with the cheaper option.", o: ["I declined the offer.", "It was a cheap trip.", "Even if it means a longer delivery time?", "The option is on page ten."], a: 2, x: "« I'm inclined to » = je penche pour → question pertinente." },
  { id: "lx036", diff: 2, g: "M", p: "I'll have the soup, and my friend will have the salad.", o: ["Yes, I have a friend.", "Great. Anything to drink with that?", "The soup is hot.", "Salads are healthy."], a: 1, x: "Contexte restaurant → suite logique." },
  { id: "lx037", diff: 3, g: "M", p: "I wonder if I should have double-checked the address before sending the package.", o: ["I wonder about stars.", "It's not too late — you can call the courier now.", "The package was big.", "I sent it by express mail."], a: 1, x: "Doute → solution pratique." },
  { id: "lx038", diff: 1, g: "M", p: "Which floor is the computer lab on?", o: ["The basement, next to the print shop.", "The lab report is due Friday.", "The lab fee is thirty dollars.", "Yes, it's a big lab."], a: 0, x: "« Which floor » → un étage." },
  { id: "lx039", diff: 2, g: "W", p: "I haven't the faintest idea where I put the receipt.", o: ["I faint easily.", "The receipt was faint.", "The idea is fine.", "Try retracing your steps from this morning."], a: 3, x: "« haven't the faintest idea » = aucune idée → conseil." },
  { id: "lx040", diff: 2, g: "W", p: "Do you know whether the shuttle runs on holidays?", o: ["Yes, I hold the shuttle.", "The holidays were great.", "I believe it's on a reduced schedule — check the website.", "It runs a mile every day."], a: 2, x: "Question indirecte (« whether ») → information nuancée." },
  { id: "lx041", diff: 3, g: "M", p: "I'm wondering whether it'd be worth it to buy the textbook new.", o: ["It was worth about twenty dollars.", "The book is very new.", "If I were you, I'd look for a used copy first.", "I wonder about the weather."], a: 2, x: "Question hésitante → conseil (« If I were you »)." },
  { id: "lx042", diff: 2, g: "M", p: "This coffee tastes awful.", o: ["I taste the sugar.", "Let me get you a fresh cup.", "It cost two dollars.", "The coffee shop is closed."], a: 1, x: "Plainte → solution du serveur." },
  { id: "lx043", diff: 3, g: "W", p: "I'm up to my ears in paperwork.", o: ["Want me to take some of it off your hands?", "My ears are fine.", "I'm up to chapter five.", "The paperwork is due Friday."], a: 0, x: "Idiome (« up to my ears ») → offre d'aide." },
  { id: "lx044", diff: 1, g: "M", p: "Do you know when the bank opens?", o: ["Banks open accounts.", "It was open yesterday.", "Yes, I know the banker.", "I think at nine, but let me check."], a: 3, x: "« When » → une heure. « Do you know » appelle une réponse informative, pas « yes »." },
  { id: "lx045", diff: 2, g: "W", p: "The bus was packed this morning.", o: ["I packed my lunch.", "The morning was cold.", "Buses are blue.", "Maybe we should leave a little earlier tomorrow."], a: 3, x: "Constat → suggestion pratique." },
  { id: "lx046", diff: 2, g: "M", p: "Is it okay if I submit the form tomorrow?", o: ["I submitted it twice.", "The form is white.", "The deadline is today, I'm afraid.", "Yes, tomorrow is Sunday."], a: 2, x: "Demande de report → refus poli." },
  { id: "lx047", diff: 2, g: "W", p: "Why don't you try the tutoring center?", o: ["I don't know why I tried.", "That's a good idea. Do I need an appointment?", "The center closes at five.", "Yes, I'm tired."], a: 1, x: "« Why don't you… » = suggestion → réaction + question pratique." },
  { id: "lx048", diff: 1, g: "W", p: "How far is the nearest subway station?", o: ["Just a five-minute walk from here.", "Yes, the subway is faster.", "It was far too crowded.", "The station opened last year."], a: 0, x: "« How far » → une distance." },
  { id: "lx049", diff: 2, g: "M", p: "You're going to love this restaurant.", o: ["I've heard great things about it.", "I loved it last time.", "It's a lovely road.", "Yes, I'm going to be late."], a: 0, x: "Phrase de promesse → réaction enthousiaste." },
  { id: "lx050", diff: 1, g: "W", p: "Do you need a ride to the airport?", o: ["Yes, the ride was fun.", "The airport is far.", "I rode a horse once.", "That would be great — my flight is at seven."], a: 3, x: "Offre → acceptation + raison." },
  { id: "lx051", diff: 2, g: "M", p: "Would you rather work in a group or on your own?", o: ["Yes, I would rather.", "My group is big.", "Honestly, I get more done on my own.", "I work at a bank."], a: 2, x: "« Would you rather » → une préférence." },
  { id: "lx052", diff: 3, g: "M", p: "I take issue with the way the survey was conducted.", o: ["I took the issue home.", "What exactly bothers you about it?", "The survey is in blue.", "The conductor was late."], a: 1, x: "« take issue with » = contester → question." },
  { id: "lx053", diff: 1, g: "W", p: "Are you using this chair?", o: ["Yes, a chair is useful.", "No, you can take it.", "It's made of wood.", "I used it yesterday."], a: 1, x: "Question pratique → réponse brève et directe." },
  { id: "lx054", diff: 1, g: "W", p: "Did you finish the reading for tomorrow?", o: ["Not yet — I'm about halfway through.", "Yes, I read the meter.", "Tomorrow is the weekend.", "The reading room is closed."], a: 0, x: "Question sur l'avancement → réponse partielle naturelle." },
  { id: "lx055", diff: 3, g: "M", p: "Rumor has it the cafeteria is switching vendors next term.", o: ["I heard the music.", "The cafeteria is on the first floor.", "The term starts in September.", "I hope the new ones have better vegetarian options."], a: 3, x: "« Rumor has it » = on dit que → souhait." },
  { id: "lx056", diff: 2, g: "M", p: "Could you give me a lift to the station?", o: ["I lift weights on Fridays.", "The station is very old.", "Sure, I'm heading that way anyway.", "The gift is on the table."], a: 2, x: "« give a lift » = déposer en voiture. Piège : « lift » = soulever." },
  { id: "lx057", diff: 2, g: "M", p: "I think there's been a mistake on my bill.", o: ["I built it myself.", "The mistake was mine.", "Let me pull up your account and take a look.", "Bills are due monthly."], a: 2, x: "Réclamation → prise en charge." },
  { id: "lx058", diff: 1, g: "W", p: "Would you like some help with those bags?", o: ["The help desk is closed.", "That would be great, thanks.", "They're made of leather.", "No, I don't like bags."], a: 1, x: "Offre d'aide → acceptation polie." },
  { id: "lx059", diff: 2, g: "M", p: "I'd like to cancel my gym membership.", o: ["Certainly. May I have your member number?", "The gym is closed.", "Members are welcome.", "I'll cancel the trip."], a: 0, x: "Contexte service client → demande d'identification." },
  { id: "lx060", diff: 2, g: "W", p: "I can't seem to open this file.", o: ["The file is in the cabinet.", "I opened the window.", "Yes, I seem tired too.", "Maybe it's saved in a different format."], a: 3, x: "Problème → hypothèse utile." },
  { id: "lx061", diff: 3, g: "M", p: "I'd appreciate it if you could keep this between us.", o: ["I appreciated the gift.", "Between us is a table.", "Keep the change, please.", "Of course, my lips are sealed."], a: 3, x: "Demande de discrétion → promesse (« my lips are sealed »)." },
  { id: "lx062", diff: 2, g: "W", p: "Are you going to the review session or studying on your own?", o: ["I review it on my own time.", "The session lasted an hour.", "I'll go — the professor said she'd cover the hard topics.", "Studying is hard."], a: 2, x: "Question à choix → un choix + justification." },
  { id: "lx063", diff: 1, g: "W", p: "Can I try this jacket on?", o: ["Yes, I tried my best.", "Of course, the fitting rooms are over there.", "The jacket is made of wool.", "I'll be on time."], a: 1, x: "Contexte magasin : indication de lieu." },
  { id: "lx064", diff: 2, g: "W", p: "It's not that I don't like the idea; it's just that the timing is off.", o: ["Fair enough. We could revisit it next semester.", "I like ideas, too.", "The timing was perfect.", "It's not that cold outside."], a: 0, x: "Réserve polie → compromis." },
  { id: "lx065", diff: 3, g: "M", p: "I'm pretty sure I aced the interview.", o: ["Don't count your chickens before they hatch.", "I ate chicken.", "I interviewed him yesterday.", "Pretty good, thanks."], a: 0, x: "Idiome : ne pas vendre la peau de l'ours." },
  { id: "lx066", diff: 2, g: "M", p: "How soon can you have this ready?", o: ["I'm already ready.", "It'll be soon enough.", "It was ready last week.", "By tomorrow afternoon at the latest."], a: 3, x: "« How soon » → délai." },
  { id: "lx067", diff: 2, g: "W", p: "Is there any way I could get an extension on the paper?", o: ["Yes, any way is fine.", "I extended my stay.", "You'd have to ask the professor, but she's usually flexible.", "The paper is due at noon."], a: 2, x: "Demande indirecte → orientation vers la bonne personne." },
  { id: "lx068", diff: 1, g: "M", p: "May I see your student ID?", o: ["I see it clearly, thanks.", "Sure, it's in my bag — one second.", "Yes, you may see the doctor.", "I saw it on the website."], a: 1, x: "Demande formelle → accord et petite précision." },
  { id: "lx069", diff: 2, g: "M", p: "Does this bus go downtown?", o: ["Down the street, to the right.", "It does, but you'll need to transfer at Elm Street.", "It's a new town.", "Yes, the bus is slow."], a: 1, x: "Question oui/non → oui + condition." },
  { id: "lx070", diff: 1, g: "W", p: "How late is the library open tonight?", o: ["Until midnight during finals week.", "It's open to all students.", "The library has many books.", "Yes, it opens tonight."], a: 0, x: "« Until when » → une heure limite." },
  { id: "lx071", diff: 2, g: "W", p: "The thing is, I've already committed to another project.", o: ["The thing is on the table.", "I committed a crime.", "Projects are boring.", "Then we'd better find someone else for this one."], a: 3, x: "« The thing is » introduit une objection → adaptation." },
  { id: "lx072", diff: 2, g: "M", p: "I've got two tickets to the game tonight, if you're interested.", o: ["The tickets are on the table.", "I'm interested in history.", "Really? I'd love to, thanks.", "The game is long."], a: 2, x: "Invitation → acceptation enthousiaste." },
  { id: "lx073", diff: 3, g: "W", p: "They've been going back and forth on that decision for weeks.", o: ["They go back home.", "They went back to the office.", "Typical. Nobody wants to take responsibility.", "The decision was made on Monday."], a: 2, x: "« back and forth » = tergiverser → commentaire critique." },
  { id: "lx074", diff: 1, g: "M", p: "Is anyone sitting here?", o: ["Yes, I'm sitting well.", "No, it's free.", "I sat there yesterday.", "It's a sitting room."], a: 1, x: "Variante de « Is this seat taken? »." },
  { id: "lx075", diff: 1, g: "M", p: "What's the Wi-Fi password?", o: ["It's on the poster next to the door.", "I forgot my phone.", "Yes, the signal is strong.", "The password is long."], a: 0, x: "Réponse qui oriente vers l'information." },
  { id: "lx076", diff: 1, g: "M", p: "What time is the next train to Chicago?", o: ["It's a very fast train.", "I've been to Chicago twice.", "The station is next to the park.", "At ten fifteen, from platform two."], a: 3, x: "« What time » → une heure." },
  { id: "lx077", diff: 2, g: "M", p: "I've been trying to reach you all morning.", o: ["I reached the top.", "Yes, I've been trying.", "Morning is the best time.", "Sorry, my phone died and I couldn't charge it."], a: 3, x: "Reproche indirect → excuse + explication." },
  { id: "lx078", diff: 3, g: "M", p: "It's a long shot, but it might be worth asking the dean.", o: ["The shot was long.", "The dean is long.", "Nothing ventured, nothing gained.", "The dean is out today."], a: 2, x: "Idiome : qui ne tente rien n'a rien." },
  { id: "lx079", diff: 2, g: "W", p: "Let's meet at the cafeteria around one.", o: ["I met her at the bank.", "One-thirty would work better for me.", "The cafeteria is on the left.", "Around the corner, please."], a: 1, x: "Proposition d'horaire → contre-proposition." },
  { id: "lx080", diff: 3, g: "M", p: "Do you have any idea how much it costs to get the transcripts sent overseas?", o: ["Last time I paid about thirty dollars, plus shipping.", "I have no idea.", "I've been overseas twice.", "I transcribed the lecture."], a: 0, x: "« Do you have any idea how much » → donner un montant." },
  { id: "lx081", diff: 2, g: "W", p: "I had no idea the application process would be so involved.", o: ["Yeah, and the essays are the hardest part.", "I had an idea yesterday.", "The process is fast.", "I'm not involved."], a: 0, x: "Constat → accord et précision." },
  { id: "lx082", diff: 2, g: "M", p: "I thought you were going to join us for dinner.", o: ["I thought so too.", "Dinner was great.", "Yes, I'll join the club.", "I was, but something came up at work."], a: 3, x: "Reproche léger → explication (« something came up »)." },
  { id: "lx083", diff: 3, g: "M", p: "I can't tell whether she's joking or not.", o: ["I tell jokes.", "She told a joke.", "With her sense of humor, it's hard to say.", "I told him a joke yesterday."], a: 2, x: "Incertitude → écho nuancé." },
  { id: "lx084", diff: 3, g: "M", p: "It goes without saying that the results are preliminary.", o: ["I went without sleep.", "Right, so we shouldn't publish them yet.", "I went without a coat.", "The results are final."], a: 1, x: "Rappel prudent → conclusion logique." },
  { id: "lx085", diff: 1, g: "M", p: "How much do I owe you for the pizza?", o: ["The pizza was delicious.", "Just ten dollars — I'll cover the rest.", "It's about six miles.", "I owe you an apology."], a: 1, x: "« How much » → un montant." },
  { id: "lx086", diff: 3, g: "W", p: "I don't mean to nag, but did you ever send the invoice?", o: ["It's on my to-do list for this afternoon, I promise.", "I never nag the nagger.", "The invoice is blue.", "Yes, I mean it."], a: 0, x: "Rappel poli → promesse." },
  { id: "lx087", diff: 1, g: "W", p: "Excuse me, is this the line for the ticket office?", o: ["The ticket was very expensive.", "No, I'm not online right now.", "The office is open until six.", "Yes, it starts just behind that sign."], a: 3, x: "Question oui/non sur un lieu : confirmation + précision. Piège : mots-échos « ticket », « line »." },
  { id: "lx088", diff: 2, g: "W", p: "I was this close to quitting the team.", o: ["I closed the door.", "Quit being funny.", "What changed your mind?", "The team is close."], a: 2, x: "« this close » = à deux doigts de → question de suivi." },
  { id: "lx089", diff: 2, g: "W", p: "I'm going to have to take a rain check on dinner.", o: ["It's raining outside.", "I checked out of the hotel.", "No problem, we'll do it another time.", "Dinner is at eight."], a: 2, x: "« take a rain check » = reporter l'invitation." },
  { id: "lx090", diff: 1, g: "W", p: "Are you free for coffee on Thursday?", o: ["I have free coffee at home.", "Thursday works — how about three o'clock?", "It was free last Thursday.", "Coffee is bad for sleep."], a: 1, x: "Invitation → acceptation + proposition d'horaire." },
  { id: "lx091", diff: 1, g: "W", p: "Do you take credit cards?", o: ["Yes, but only for amounts over ten dollars.", "I credit him with the idea.", "The card is in my wallet.", "No, I took the bus."], a: 0, x: "Question oui/non sur le paiement → réponse précise. Piège : « take » mal interprété." },
  { id: "lx092", diff: 3, g: "M", p: "The deadline's coming up fast, and we're nowhere near finished.", o: ["The deadline is on Friday.", "Coming up with ideas is hard.", "I'm near the building.", "Then let's divide what's left and push through tonight."], a: 3, x: "Constat de retard → plan d'action." },
  { id: "lx093", diff: 3, g: "M", p: "Would you happen to know whether the department offers any funding for conferences?", o: ["The funding was approved last year.", "The conference was in June.", "Yes, I happen to be here.", "Not off the top of my head, but the secretary should know."], a: 3, x: "« off the top of my head » = de mémoire, sans vérifier." },
  { id: "lx094", diff: 3, g: "M", p: "It never occurred to me that the data might be flawed.", o: ["It occurred in May.", "Flaws are in glass.", "We should rerun the analysis to be on the safe side.", "Never say never."], a: 2, x: "Réaction scientifique → vérification." },
  { id: "lx095", diff: 1, g: "W", p: "Where should I leave my coat?", o: ["I left it at home.", "There's a coat rack by the entrance.", "It's a long coat.", "The coat is very warm."], a: 1, x: "« Where should I… » → une indication." },
  { id: "lx096", diff: 1, g: "W", p: "What's your major?", o: ["Environmental science, with a minor in economics.", "I'm a major in the army.", "It's a major problem.", "Yes, it's my major."], a: 0, x: "Piège : « major » polysémique ; ici, matière principale." },
  { id: "lx097", diff: 2, g: "W", p: "Would you mind taking a quick look at my schedule?", o: ["Not at all — let me see what you've got.", "Yes, I mind the schedule.", "I looked at the clock.", "The schedule is on the door."], a: 0, x: "« Would you mind » → « Not at all » = d'accord." },
  { id: "lx098", diff: 2, g: "W", p: "I just got my midterm back.", o: ["I got it back from the library.", "The midterm is in March.", "I got it from the store.", "How did you do?"], a: 3, x: "Annonce → question de suivi naturelle." },
  { id: "lx099", diff: 1, g: "M", p: "How was the exam?", o: ["The exam is on Friday.", "It lasted two hours.", "Tougher than I expected, but I think I did okay.", "I'll take it tomorrow."], a: 2, x: "« How was… » → une impression sur le passé." },
  { id: "lx100", diff: 2, g: "M", p: "I'm sorry to bother you, but you're parked in my spot.", o: ["I park at the mall.", "Oh, I'm so sorry — I'll move my car right now.", "Yes, it's a nice spot.", "I didn't bother with it."], a: 1, x: "Plainte polie → excuse + action." },
  { id: "lx101", diff: 1, g: "M", p: "How do you like your new apartment?", o: ["I moved there in June.", "It's small, but the location is perfect.", "Yes, apartments are expensive.", "The rent is due on the first."], a: 1, x: "« How do you like… » = qu'en penses-tu ? → une opinion." },
  { id: "lx102", diff: 3, g: "W", p: "He was let off with a warning.", o: ["Lucky him — I would've expected a fine.", "He left at noon.", "The warning was loud.", "I turned the lights off."], a: 0, x: "« let off with a warning » = s'en tirer avec un avertissement." },
  { id: "lx103", diff: 1, g: "M", p: "Do you have any rooms available this weekend?", o: ["I'm available on Sunday.", "The weekend was relaxing.", "Yes, I room with Tom.", "We have one double left, at ninety dollars a night."], a: 3, x: "Contexte hôtel. Piège : « available » répété dans un autre contexte." },
  { id: "lx104", diff: 2, g: "W", p: "I'm so nervous about the presentation.", o: ["I presented it yesterday.", "I'm not nervous at all.", "You'll be fine — you know the material well.", "It's very long."], a: 2, x: "Réconfort approprié." },
  { id: "lx105", diff: 2, g: "W", p: "We haven't heard the last of this issue.", o: ["I haven't heard the news.", "This issue is a magazine.", "I wouldn't be surprised if it comes up at the next meeting.", "I heard it last night."], a: 2, x: "« haven't heard the last of » = ce n'est pas fini." },
  { id: "lx106", diff: 2, g: "W", p: "I'm thinking about taking a gap year.", o: ["That's a wide gap.", "Have you talked to your parents about it yet?", "I took a year off, too.", "The year is almost over."], a: 1, x: "Projet annoncé → question de suivi appropriée." },
  { id: "lx107", diff: 1, g: "W", p: "Can you recommend a good restaurant around here?", o: ["There's a nice Italian place two blocks down.", "Yes, I'm very good at it.", "The recommendation letter is ready.", "I eat out around noon."], a: 0, x: "Demande de recommandation → suggestion concrète." },
  { id: "lx108", diff: 3, g: "W", p: "I wasn't aware that the policy had changed.", o: ["I'm aware of the deadline.", "The policy is fair.", "I changed my mind.", "It was announced in an email last week."], a: 3, x: "Réponse informative sur la source." },
  { id: "lx109", diff: 3, g: "M", p: "It's anybody's guess who will win the election.", o: ["I guessed the answer.", "Nobody is winning.", "The election is at noon.", "True, the polls are too close to call."], a: 3, x: "« anybody's guess » = personne ne sait." },
  { id: "lx110", diff: 2, g: "M", p: "Would you care for a refill?", o: ["I don't care for fill.", "The cup is full.", "Yes, please, just half a cup.", "I filled out the form."], a: 2, x: "« Would you care for » = voulez-vous ? (offre polie)." },
  { id: "lx111", diff: 1, g: "M", p: "Where's the nearest ATM?", o: ["I withdrew some cash yesterday.", "Inside the lobby, next to the elevators.", "At around five o'clock.", "The machine is very modern."], a: 1, x: "« Where » → un lieu." },
  { id: "lx112", diff: 3, g: "W", p: "The lecture was fascinating, though I could've done without the three-hour length.", o: ["Tell me about it — my legs went numb.", "I did without lunch.", "It lasted until three.", "The lecture hall was cold."], a: 0, x: "« Tell me about it » = j'en sais quelque chose (accord)." },
  { id: "lx113", diff: 2, g: "W", p: "Do you mind if I ask you a personal question?", o: ["Go ahead — I might not answer, though.", "Yes, it's personal.", "I don't ask questions.", "No, I don't mind a minute."], a: 0, x: "Question de politesse : « Go ahead » = vas-y." },
  { id: "lx114", diff: 2, g: "W", p: "Between you and me, I think the department is in for some big changes.", o: ["Between classes, I took a nap.", "I'm in for dinner.", "The big meeting is on Friday.", "I've picked up on that, too — people have been whispering."], a: 3, x: "« Between you and me » = confidence → confirmation." },
  { id: "lx115", diff: 2, g: "W", p: "Did you get a chance to look at my draft?", o: ["I got a chance to travel.", "There's a cold draft in here.", "I did. Overall it's good, but the intro needs work.", "I'll take my chances."], a: 2, x: "« get a chance » = trouver le temps. Réponse avec retour." },
  { id: "lx116", diff: 2, g: "M", p: "I was hoping to extend my library loan.", o: ["The loan was approved.", "You can renew it online if no one has requested it.", "I extended my vacation.", "Yes, I'm hoping too."], a: 1, x: "« I was hoping to… » = demande indirecte → procédure." },
  { id: "lx117", diff: 1, g: "M", p: "Do you want to share a taxi?", o: ["The taxi was yellow.", "Good idea — we're going the same way.", "I don't share my secrets.", "It costs twenty dollars."], a: 1, x: "Proposition → acceptation." },
  { id: "lx118", diff: 1, g: "W", p: "I'd like to open a savings account.", o: ["Certainly. Do you have some form of ID with you?", "Savings are a good idea, thanks.", "The account was closed yesterday.", "I opened the door for her."], a: 0, x: "Contexte banque : le conseiller demande les documents nécessaires." },
  { id: "lx119", diff: 1, g: "W", p: "Is there a discount for students?", o: ["I discounted that idea.", "I paid the full amount last time.", "I counted them twice.", "Yes, ten percent with a valid ID."], a: 3, x: "Question oui/non → oui + condition." },
  { id: "lx120", diff: 2, g: "W", p: "Do you want to split an appetizer?", o: ["I split the check.", "An app is on my phone.", "Sure, how about the spinach dip?", "I want to go home."], a: 2, x: "Proposition au restaurant → acceptation + choix." },
  { id: "lx121", diff: 3, g: "M", p: "The more I think about it, the less sense the plan makes.", o: ["I think a lot.", "I plan to think about it later.", "That's what I've been saying all along.", "I'll think about the lesson."], a: 2, x: "Corrélatif (« the more…, the less… ») → accord." },
  { id: "lx122", diff: 2, g: "M", p: "What did the doctor say about your knee?", o: ["The knee is very sore.", "I should rest it for two weeks, no running.", "She said it on Monday.", "It's a nice doctor."], a: 1, x: "Discours rapporté : on répond par le contenu du conseil." },
  { id: "lx123", diff: 3, g: "M", p: "It's about time the university upgraded the dining hall.", o: ["Agreed — the food hasn't changed in years.", "It takes about an hour.", "The hall has been repainted.", "Time is money."], a: 0, x: "« It's about time » = il était temps → accord." },
  { id: "lx124", diff: 3, g: "M", p: "Whatever you do, don't mention the layoffs to the interns.", o: ["I do whatever I want.", "The interns are late.", "I mentioned it to her.", "My lips are sealed."], a: 3, x: "Consigne de discrétion → promesse." },
  { id: "lx125", diff: 2, g: "M", p: "I'm having second thoughts about the trip.", o: ["I had a second cup.", "The thought was short.", "Trips are fun.", "Is it the cost, or something else?"], a: 3, x: "Hésitation → question de clarification." },
  { id: "lx126", diff: 1, g: "M", p: "Did you bring your textbook today?", o: ["I took the book home.", "The text was very long.", "Yes, but I forgot my notebook.", "Today is a holiday."], a: 2, x: "Question au passé → réponse + nuance." },
  { id: "lx127", diff: 2, g: "W", p: "I'd be lying if I said I wasn't a little disappointed.", o: ["I'm lying on the sofa.", "I can tell. Do you want to talk about it?", "Say it again, please.", "I appointed her yesterday."], a: 1, x: "Aveu émotionnel → réponse empathique." },
  { id: "lx128", diff: 2, g: "W", p: "I'm calling about the apartment you advertised.", o: ["Yes, it's still available. Would you like to see it?", "I called you yesterday.", "The ad was in the paper.", "It's about an apartment."], a: 0, x: "Contexte location : réponse de l'agent." },
  { id: "lx129", diff: 2, g: "W", p: "I forgot to bring my laptop charger.", o: ["You can use mine — I'm not using it right now.", "The charge was twenty dollars.", "I forgot the question.", "The charger is heavy."], a: 0, x: "Problème → offre d'aide." },
  { id: "lx130", diff: 1, g: "W", p: "How many credits are you taking this semester?", o: ["I take the bus to campus.", "Credits appear at the end of films.", "About twenty minutes.", "Fifteen, so I'm pretty busy."], a: 3, x: "« How many » → un nombre." },
  { id: "lx131", diff: 2, g: "W", p: "I might as well join the study group, since I'm not getting anywhere on my own.", o: ["I've been there before.", "I might not make it.", "That's the spirit — we meet on Tuesdays.", "The group meets in the library."], a: 2, x: "« might as well » = autant le faire → encouragement." },
  { id: "lx132", diff: 3, g: "M", p: "You can't be serious about moving to Alaska.", o: ["I'm serious about my studies.", "I am — I've already found a job there.", "Alaska is very cold.", "Moving is a verb."], a: 1, x: "Incrédulité → confirmation avec argument." },
  { id: "lx133", diff: 3, g: "W", p: "I'm not too keen on the idea of working all weekend.", o: ["I'm keen on keeping fit.", "Me neither. Can we split the work with Dan?", "Weekends are for relaxing.", "The idea is brilliant."], a: 1, x: "« not too keen on » = peu enthousiaste → solution." },
  { id: "lx134", diff: 1, g: "M", p: "Would you like to see the dessert menu?", o: ["Just coffee for me, thanks.", "The menu is on the wall.", "Yes, I'd like to see you.", "I saw a movie last night."], a: 0, x: "Question au restaurant → refus poli avec alternative." },
  { id: "lx135", diff: 1, g: "M", p: "What do you do on weekends?", o: ["I did it last weekend.", "The weekend is two days.", "Yes, I do.", "I usually go hiking with some friends."], a: 3, x: "« What do you do » → habitudes (présent simple)." },
  { id: "lx136", diff: 2, g: "W", p: "Please remind me to send that email before I leave.", o: ["I remember the deadline.", "Please leave it here.", "Will do — I'll nudge you at four.", "I reminded him yesterday."], a: 2, x: "« Will do » = d'accord, je le ferai." },
  { id: "lx137", diff: 1, g: "W", p: "What kind of music do you like?", o: ["I like it very much, thanks.", "The music starts at eight.", "Mostly jazz, and some classical.", "I played it yesterday."], a: 2, x: "« What kind of » → une catégorie." },
  { id: "lx138", diff: 3, g: "M", p: "I'm swamped with assignments at the moment.", o: ["I swim every morning.", "Why not ask for an extension on one of them?", "The moment is nice.", "I assigned the reading."], a: 1, x: "« swamped » = débordé → suggestion." },
  { id: "lx139", diff: 2, g: "W", p: "I'm afraid this seat is reserved.", o: ["Oh, sorry. I'll find another one.", "Yes, I'm afraid of him too.", "I reserved a table last night.", "It's very comfortable."], a: 0, x: "Remarque polie → excuse et solution." },
  { id: "lx140", diff: 3, g: "M", p: "The new policy goes into effect on the first of the month.", o: ["It has no side effects.", "The first of May is nice.", "I'm going into the office.", "That doesn't leave us much time to adjust."], a: 3, x: "Annonce → réaction sur le délai." },
  { id: "lx141", diff: 3, g: "W", p: "Looking back, I should've asked for help sooner.", o: ["I looked at the back.", "I looked back at my notes.", "I helped him later.", "Hindsight is twenty-twenty, as they say."], a: 3, x: "Idiome (« hindsight is 20/20 ») → réconfort." },
  { id: "lx142", diff: 3, g: "W", p: "We're a little short-staffed this week.", o: ["The staff meeting is on Monday.", "I'm on the staff of the paper.", "In that case, I can stay late on Thursday.", "This week is long."], a: 2, x: "« short-staffed » = en sous-effectif → offre d'aide." },
  { id: "lx143", diff: 2, g: "W", p: "I'd steer clear of that professor if I were you.", o: ["I steered the boat.", "Really? I was about to sign up for her seminar.", "Clear sky today.", "If I were you, I would."], a: 1, x: "Conseil d'éviter → surprise et question." },
  { id: "lx144", diff: 1, g: "W", p: "Is it all right if I turn on the heater?", o: ["Sure, it's freezing in here.", "The heater was broken in July.", "Right, it's all fine.", "Right, I heard it all."], a: 0, x: "Demande de permission → accord avec justification." },
  { id: "lx145", diff: 3, g: "M", p: "Given the circumstances, I think we did the best we could.", o: ["I suppose so, but I wish we had more time.", "The circumstances are bad.", "Yes, we could.", "The best is the last."], a: 0, x: "Bilan résigné." },
  { id: "lx146", diff: 3, g: "M", p: "I didn't think it'd be so hard to find a parking space on campus.", o: ["I thought about it for hours.", "The space is reserved for staff.", "I parked the bike.", "You have to arrive before eight, or forget it."], a: 3, x: "Constat → conseil expérimenté." },
  { id: "lx147", diff: 2, g: "M", p: "I'd like a window seat, if possible.", o: ["I sit by the door.", "The window is open.", "Let me see what's available on that flight.", "Yes, I'd like that too."], a: 2, x: "Contexte voyage : agent qui vérifie la disponibilité." },
  { id: "lx148", diff: 3, g: "M", p: "I could use some fresh air after that meeting.", o: ["The air is fresh.", "Let's take a walk around the quad.", "I could use the meeting room.", "Meetings are long."], a: 1, x: "« I could use » = j'aurais bien besoin de → suggestion." },
  { id: "lx149", diff: 2, g: "M", p: "You wouldn't happen to know where the dean's office is, would you?", o: ["No, I wouldn't mind.", "It's on the top floor, at the end of the hall.", "The dean is very kind.", "I happen to love this place."], a: 1, x: "Question indirecte polie → donner le lieu." },
  { id: "lx150", diff: 2, g: "W", p: "She's been burning the candle at both ends lately.", o: ["No wonder she looks so tired.", "She burned a candle in church.", "The ends are near.", "She bought a candle yesterday."], a: 0, x: "Idiome : s'épuiser → réaction logique (« No wonder »)." }
);

CONTENT.ann.push(
  {"id":"nx001","diff":1,"g":"W","ctx":"Listen to an announcement at a campus bookstore.","text":"Good morning, shoppers. This week only, the campus bookstore is offering twenty percent off all notebooks, pens, and backpacks. Students who show a valid ID will receive an extra five dollars off any purchase over fifty dollars. The sale ends on Sunday at closing time. Please note that textbooks are not included in this offer, but used copies are available on the second floor at much lower prices. We also have a new coffee corner near the entrance. Thank you for shopping with us.","qs":[{"q":"What is the announcement mainly about?","o":["A weekly sale at the bookstore","A change in store hours","A new textbook policy","A job opening"],"a":0,"x":"Promotion de la semaine."},{"q":"What extra benefit do students with ID receive?","o":["A free notebook","Five dollars off a purchase over fifty dollars","Free coffee","Twenty percent off textbooks"],"a":1,"x":"« an extra five dollars off any purchase over fifty dollars »."},{"q":"Where can students find cheaper textbooks?","o":["At the coffee corner","On the second floor","Near the entrance","Online only"],"a":1,"x":"Exemplaires d'occasion au 2e étage."}]},
  {"id":"nx002","diff":1,"g":"M","ctx":"Listen to an announcement at a train station.","text":"Attention, passengers. The ten forty express train to Boston has been delayed by about twenty minutes because of a signal problem outside the city. The train will now depart from platform four instead of platform two. Passengers who have already gone to platform two should walk down the stairs and follow the signs. We apologize for the inconvenience. Information about connecting trains is available at the service desk in the main hall.","qs":[{"q":"Why is the train late?","o":["Bad weather","A signal problem","A shortage of drivers","Track repairs at the station"],"a":1,"x":"« a signal problem outside the city »."},{"q":"What has changed about the departure?","o":["The destination","The platform","The ticket price","The driver"],"a":1,"x":"Quai 4 au lieu du quai 2."},{"q":"Where can passengers learn about connecting trains?","o":["On platform four","At the service desk","On the website","From the driver"],"a":1,"x":"« at the service desk in the main hall »."}]},
  {"id":"nx003","diff":2,"g":"W","ctx":"Listen to an announcement from the student housing office.","text":"Hello, residents. This is a reminder that the annual fire safety inspection will take place on Tuesday between nine and four. Inspectors will visit every room, so please make sure someone is available, or leave your door unlocked if you'll be at class. You don't need to be present, but any items blocking exits or heaters will be reported. Also, candles and extension cords with more than four outlets are not allowed, and will be removed. If you have questions, stop by the housing office or email us.","qs":[{"q":"What will happen on Tuesday?","o":["A fire drill","A safety inspection of the rooms","A cleaning of the heaters","A meeting for residents"],"a":1,"x":"Inspection annuelle de sécurité incendie."},{"q":"What can residents do if they will be at class?","o":["Give their key to the inspector","Leave their door unlocked","Reschedule the inspection","Ask a friend to be present"],"a":1,"x":"« leave your door unlocked »."},{"q":"What might be removed from rooms?","o":["Heaters","Candles and large extension cords","Exit signs","Blankets"],"a":1,"x":"Bougies et rallonges de plus de 4 prises."},{"q":"What does the speaker imply about attending the inspection?","o":["It is mandatory for all students","It is not necessary to be there","It is only for new residents","It must be arranged in advance"],"a":1,"x":"« You don't need to be present »."}]},
  {"id":"nx004","diff":2,"g":"M","ctx":"Listen to an announcement at a company staff meeting.","text":"Good morning, team. A few updates before we begin. First, our quarterly sales figures are in, and we exceeded our target by eight percent, so congratulations to everyone. Second, because of the renovation, the third floor kitchen will be closed for two weeks starting Monday. Please use the one on the fifth floor in the meantime. Finally, the annual performance reviews will take place next month. Your manager will send you a calendar invitation by the end of this week, so keep an eye on your inbox.","qs":[{"q":"What is the good news announced?","o":["A new office opening","Sales exceeded the target","A salary increase","A holiday bonus"],"a":1,"x":"Objectif dépassé de 8 %."},{"q":"Why will the third floor kitchen be closed?","o":["It is being renovated","It is too dirty","There is a staff shortage","It is being converted into an office"],"a":0,"x":"« because of the renovation »."},{"q":"What should employees do by the end of the week?","o":["Submit a self-evaluation","Watch for a calendar invitation","Move to the fifth floor","Meet their manager"],"a":1,"x":"« keep an eye on your inbox »."}]},
  {"id":"nx005","diff":3,"g":"W","ctx":"Listen to an announcement from the university registrar.","text":"Good afternoon. I'd like to clarify the recent change to the course withdrawal policy. Previously, students could withdraw from a class up to the tenth week without any record on their transcript. Beginning next term, a withdrawal after the sixth week will appear as a W on the transcript, although it won't affect your grade point average. The change is intended to encourage students to make decisions earlier rather than staying in courses they're unlikely to complete. Exceptions will still be considered for documented medical or family emergencies. Please consult your advisor if you're unsure how this affects your plans.","qs":[{"q":"What is the main purpose of the announcement?","o":["To explain a change in withdrawal policy","To announce new courses","To change the grading scale","To remind students of deadlines"],"a":0,"x":"Clarification de la nouvelle politique de retrait."},{"q":"What will happen if a student withdraws in week eight next term?","o":["Nothing will appear on the transcript","A W will appear on the transcript","The GPA will drop","The student will need approval"],"a":1,"x":"Retrait après la semaine 6 → mention W."},{"q":"Why was the policy changed?","o":["To increase tuition income","To encourage earlier decisions","To reduce the number of courses","To protect GPAs"],"a":1,"x":"Encourager les décisions plus tôt."},{"q":"Who might still receive an exception?","o":["Students who are failing","Students with documented emergencies","Students in their final year","Students with advisors' approval only"],"a":1,"x":"Urgences médicales ou familiales documentées."}]},
  {"id":"nx006","diff":2,"g":"M","ctx":"Listen to an announcement on an airplane.","text":"Ladies and gentlemen, this is your captain speaking. We've started our descent into Denver, and we expect to land in about thirty minutes. The weather in Denver is clear, with a temperature of twelve degrees Celsius. We'll be a few minutes ahead of schedule thanks to a strong tailwind. The flight attendants will be coming through the cabin to collect any trash. Please make sure your seat backs and tray tables are in the upright position, and keep your seat belt fastened until the sign is turned off after we reach the gate. Thank you for flying with us.","qs":[{"q":"When will the plane land?","o":["In about ten minutes","In about thirty minutes","In about an hour","Right now"],"a":1,"x":"« in about thirty minutes »."},{"q":"Why will the flight arrive early?","o":["A tailwind is helping","The plane is flying faster by design","There is little traffic at the airport","The route was changed"],"a":0,"x":"« a strong tailwind »."},{"q":"What should passengers do now?","o":["Collect their luggage","Put their seats and tray tables upright","Walk to the gate","Fill out a form"],"a":1,"x":"Dossiers et tablettes relevés."}]},
  {"id":"nx007","diff":3,"g":"W","ctx":"Listen to an announcement made by a conference organizer.","text":"Welcome back, everyone, and thank you for your patience. I'm afraid the keynote speaker, Dr. Hall, has been held up at the airport because of fog, so we've had to rearrange this afternoon's program. Instead of her address at two, we'll begin with the panel on research funding, which was originally scheduled for four. Dr. Hall is now expected to arrive around five and will speak at six, right before the closing dinner. Those of you who planned to leave early might want to adjust your travel plans. Please also note that the closing dinner has been moved to the garden room.","qs":[{"q":"Why was the program changed?","o":["A speaker was delayed","A room was unavailable","The panel was cancelled","There was a power failure"],"a":0,"x":"Intervenante retenue à l'aéroport à cause du brouillard."},{"q":"What will take place at two?","o":["The keynote address","The panel on research funding","The closing dinner","A coffee break"],"a":1,"x":"Le panel est avancé à 14 h."},{"q":"What does the organizer suggest to people who planned to leave early?","o":["Skip the panel","Change their travel arrangements","Attend the dinner","Contact Dr. Hall"],"a":1,"x":"« might want to adjust your travel plans »."},{"q":"What else has changed?","o":["The date of the conference","The location of the dinner","The title of the keynote","The panel members"],"a":1,"x":"Dîner dans la « garden room »."}]},
  {"id":"nx008","diff":1,"g":"M","ctx":"Listen to an announcement at a university gym.","text":"Hi, everyone. Starting next Monday, the gym will have new opening hours. We will open at six in the morning and close at ten at night, Monday through Friday. On weekends, we'll be open from eight to six. We're also starting free yoga classes every Wednesday at noon. You don't need to register. Just bring your own mat. Please remember to wipe down the machines after you use them. Thanks, and have a great workout.","qs":[{"q":"What is changing next Monday?","o":["The membership fee","The gym hours","The equipment","The staff"],"a":1,"x":"Nouveaux horaires."},{"q":"When will the yoga classes take place?","o":["Every Monday morning","Wednesdays at noon","Saturdays at six","Fridays at ten"],"a":1,"x":"« every Wednesday at noon »."},{"q":"What should people bring to yoga?","o":["A registration form","Their own mat","A towel","Water only"],"a":1,"x":"« Just bring your own mat »."}]},
  {"id":"nx009","diff":2,"g":"W","ctx":"Listen to an announcement at the start of a workshop.","text":"Welcome, everyone, to today's workshop on academic writing. Before we begin, I'd like to go over a few details. The session will last about two hours, with a ten-minute break halfway through. Handouts are on the table by the door, and the slides will be emailed to you afterward, so there's no need to photograph them. We'll spend the first hour on structuring an argument and the second on citing sources. If you have a draft with you, feel free to use it in the exercises. Questions are welcome at any time.","qs":[{"q":"How long is the workshop?","o":["About one hour","About two hours","About three hours","All day"],"a":1,"x":"« about two hours »."},{"q":"How will participants get the slides?","o":["From the table","By email afterward","On the website","They will not get them"],"a":1,"x":"« emailed to you afterward »."},{"q":"What will be covered in the second hour?","o":["Structuring an argument","Citing sources","Editing drafts","Presentations"],"a":1,"x":"2e heure : citer des sources."},{"q":"What does the speaker suggest participants may do with their drafts?","o":["Hand them in","Use them in exercises","Throw them away","Submit them online"],"a":1,"x":"« feel free to use it in the exercises »."}]},
  {"id":"nx010","diff":3,"g":"M","ctx":"Listen to an announcement from a city transit authority.","text":"This is a service notice for commuters. Beginning the first of next month, the transit authority will introduce a new fare system. Instead of paying per trip, riders will be charged a daily fare that is capped at six dollars, regardless of how many journeys they make. Monthly passes will remain available, but their price will increase by about four percent. Officials say the change is meant to simplify payment and make short, frequent trips cheaper. Riders who currently hold prepaid cards will have their balance carried over automatically, and no action is necessary. More details can be found on the authority's website.","qs":[{"q":"What change is being announced?","o":["A new fare system with a daily cap","The end of monthly passes","New bus routes","A fare freeze"],"a":0,"x":"Tarif journalier plafonné à 6 $."},{"q":"What will happen to monthly passes?","o":["They will be discontinued","They will cost slightly more","They will be free","They will stay at the same price"],"a":1,"x":"Hausse d'environ 4 %."},{"q":"Who benefits most from the new system?","o":["People who take few, long trips","People who make several short trips a day","Tourists","Monthly pass holders"],"a":1,"x":"Trajets courts et fréquents moins chers."},{"q":"What must current prepaid card holders do?","o":["Register online","Exchange their cards","Nothing","Pay a fee"],"a":2,"x":"« no action is necessary »."}]},
  {"id":"nx011","diff":2,"g":"W","ctx":"Listen to an announcement by a student club president.","text":"Hi, everyone, and thanks for coming to the first meeting of the semester. I have a few quick announcements. Our hiking trip to Red Rock Canyon is scheduled for the second Saturday of October. The cost is fifteen dollars, which covers transportation and lunch, and you can pay at the next meeting. We're also looking for someone to take over as treasurer, since Priya is graduating. If you're interested, please talk to me after the meeting. Last, we're collecting donations of used hiking boots for a local youth program, so check your closets.","qs":[{"q":"What does the fifteen dollars cover?","o":["Equipment rental","Transportation and lunch","Club membership","Camping fees"],"a":1,"x":"Transport et déjeuner."},{"q":"Why does the club need a new treasurer?","o":["Priya is graduating","Priya is traveling","Nobody wants the job","The club is closing"],"a":0,"x":"Priya termine ses études."},{"q":"What are members asked to donate?","o":["Money","Used hiking boots","Backpacks","Food"],"a":1,"x":"Vieilles chaussures de randonnée."}]},
  {"id":"nx012","diff":3,"g":"M","ctx":"Listen to an announcement from a university IT department.","text":"This is a message from the IT department regarding scheduled maintenance. On Saturday night, from eleven p.m. until about five a.m., the student portal, email, and the online library catalog will be unavailable while we upgrade our servers. Although the work is expected to finish by five, there's a small chance of delays, so please don't count on access early Sunday morning. If you have an assignment due on Sunday, we strongly recommend submitting it before Saturday evening, as instructors have been told that technical downtime won't be accepted as an excuse for late work. The campus Wi-Fi will not be affected.","qs":[{"q":"What will be unavailable during the maintenance?","o":["Campus Wi-Fi","The student portal, email, and library catalog","All computers on campus","Only email"],"a":1,"x":"Portail, e-mail et catalogue."},{"q":"What does the speaker advise students with Sunday deadlines to do?","o":["Ask for an extension","Submit work before Saturday evening","Use the Wi-Fi","Contact IT"],"a":1,"x":"Rendre le travail avant samedi soir."},{"q":"What does the speaker imply about late assignments?","o":["Instructors will be flexible about downtime","Downtime will not excuse lateness","Late work will be graded higher","The deadline will be moved automatically"],"a":1,"x":"« won't be accepted as an excuse »."},{"q":"Why does the speaker say not to count on access early Sunday?","o":["The work may take longer than planned","The portal closes permanently","The campus is closed","Servers are being replaced for good"],"a":0,"x":"Risque de retard."}]},
  {"id":"nx013","diff":1,"g":"W","ctx":"Listen to an announcement in a campus dining hall.","text":"Hello, students. Please note that the dining hall will close early today, at six instead of eight, because of a staff training session. Dinner will be served from five to six. If you have a meal plan, you can also use your card at the snack bar in the student center, which will stay open until midnight. Breakfast will start at seven tomorrow as usual. We apologize for the change.","qs":[{"q":"Why will the dining hall close early?","o":["Staff training","A broken oven","A holiday","A power cut"],"a":0,"x":"Formation du personnel."},{"q":"Where can students use their meal plan tonight after six?","o":["At the library","At the snack bar in the student center","Nowhere","At the gym"],"a":1,"x":"Snack bar jusqu'à minuit."},{"q":"When does breakfast start tomorrow?","o":["At six","At seven","At eight","At nine"],"a":1,"x":"7 h comme d'habitude."}]},
  {"id":"nx014","diff":3,"g":"M","ctx":"Listen to an announcement by a professor at the end of a course.","text":"As we wrap up, a word about the final project. A number of you have asked whether groups may present remotely. The answer is yes, provided you inform me by Friday and test your connection in advance. However, I'd caution against assuming a remote presentation is easier. In my experience, groups that present online tend to lose the audience's attention more quickly, so you'll need to plan your visuals carefully. Also, I've heard that some of you are planning to combine this project with your capstone. That's fine in principle, but you'll need written approval from both instructors beforehand.","qs":[{"q":"Under what condition may groups present remotely?","o":["They must have a medical reason","They must tell the professor by Friday and test their connection","They must present first","They must record the talk"],"a":1,"x":"Prévenir avant vendredi et tester la connexion."},{"q":"What does the professor imply about remote presentations?","o":["They are easier","They can be harder to keep engaging","They are graded more strictly","They are not allowed"],"a":1,"x":"On perd plus vite l'attention."},{"q":"What is required to combine the project with a capstone?","o":["Approval from both instructors in writing","A longer presentation","A new group","Nothing special"],"a":0,"x":"Autorisation écrite des deux enseignants."}]}
);
